CREATE POLICY hiring6_email_scope ON public.email_log AS RESTRICTIVE FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.applications a WHERE a.id=application_id));
CREATE FUNCTION hiring_private.hiring_staff_contacts(_ids uuid[]) RETURNS TABLE(user_id uuid,email text,full_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT p.user_id,p.email,p.full_name FROM public.profiles p WHERE p.user_id=ANY(_ids) AND (public.hiring_profile_access(p.user_id) OR (public.is_hiring_staff(auth.uid()) AND EXISTS(SELECT 1 FROM public.hiring_user_roles r WHERE r.user_id=p.user_id))) $$;
CREATE FUNCTION public.hiring_staff_contacts(_ids uuid[]) RETURNS TABLE(user_id uuid,email text,full_name text) LANGUAGE sql STABLE SET search_path='' AS $$ SELECT * FROM hiring_private.hiring_staff_contacts(_ids) $$;
CREATE FUNCTION hiring_private.hiring_save_review(_application_id uuid,_skill int,_thinking int,_commitment int) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'reviewer')) OR NOT EXISTS(SELECT 1 FROM public.applications WHERE id=_application_id AND NOT is_draft) THEN RAISE EXCEPTION 'Reviewer access required' USING ERRCODE='42501'; END IF;
 IF _skill NOT BETWEEN 1 AND 5 OR _thinking NOT BETWEEN 1 AND 5 OR _commitment NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Scores must be from 1 to 5'; END IF;
 IF EXISTS(SELECT 1 FROM public.application_reviews WHERE application_id=_application_id AND reviewer_id=auth.uid()) THEN UPDATE public.application_reviews SET skill_score=_skill,thinking_score=_thinking,commitment_score=_commitment WHERE application_id=_application_id AND reviewer_id=auth.uid(); ELSE INSERT INTO public.application_reviews(application_id,reviewer_id,skill_score,thinking_score,commitment_score) VALUES(_application_id,auth.uid(),_skill,_thinking,_commitment); END IF; END $$;
CREATE FUNCTION public.hiring_save_review(_application_id uuid,_skill int,_thinking int,_commitment int) RETURNS void LANGUAGE sql SET search_path='' AS $$ SELECT hiring_private.hiring_save_review(_application_id,_skill,_thinking,_commitment) $$;
CREATE FUNCTION hiring_private.hiring_assign_reviewer(_ids uuid[],_reviewer uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid; BEGIN
 IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'reviewer')) OR NOT(public.has_role(_reviewer,'reviewer') OR public.has_role(_reviewer,'admin')) THEN RAISE EXCEPTION 'Reviewer assignment access required' USING ERRCODE='42501'; END IF;
 FOREACH a IN ARRAY _ids LOOP IF NOT EXISTS(SELECT 1 FROM public.applications WHERE id=a AND NOT is_draft) THEN RAISE EXCEPTION 'Submitted application required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.application_reviews WHERE application_id=a) THEN INSERT INTO public.application_reviews(application_id,reviewer_id,assigned_reviewer_id) VALUES(a,auth.uid(),_reviewer); ELSE UPDATE public.application_reviews SET assigned_reviewer_id=_reviewer WHERE application_id=a; END IF; END LOOP; END $$;
CREATE FUNCTION public.hiring_assign_reviewer(_ids uuid[],_reviewer uuid) RETURNS void LANGUAGE sql SET search_path='' AS $$ SELECT hiring_private.hiring_assign_reviewer(_ids,_reviewer) $$;
CREATE FUNCTION public.hiring6_interview_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN
 IF current_user='authenticated' AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Use checked interview operations' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hiring6_interview_guard BEFORE UPDATE ON public.interviews FOR EACH ROW EXECUTE FUNCTION public.hiring6_interview_guard();
REVOKE ALL ON FUNCTION public.hiring6_interview_guard() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','hiring_private') AND p.proname IN ('hiring_staff_contacts','hiring_save_review','hiring_assign_reviewer') LOOP EXECUTE 'REVOKE ALL ON FUNCTION '||f.signature||' FROM PUBLIC,anon'; EXECUTE 'GRANT EXECUTE ON FUNCTION '||f.signature||' TO authenticated,service_role'; END LOOP; END $$;